import random
N = 24
fixed = {9:-1, 14:1, 15:-1, 22:-1}
cfix = {3:0, 9:-2, 14:-1, 19:0}

def c_k(seq, k):
    return sum(seq[i]*seq[i+k] for i in range(N-k))

# Local search
def merit(seq):
    return sum(c_k(seq,k)**2 for k in range(1,N))

def cons_ok(seq):
    for k,v in cfix.items():
        if c_k(seq,k) != v:
            return False
    return True

free = [i for i in range(N) if i not in fixed]
random.seed(42)
best_global = None

for restart in range(200):
    seq = [0]*N
    for i,v in fixed.items(): seq[i] = v
    for i in free: seq[i] = random.choice([-1,1])

    # local search: flip pairs to keep... actually just flip single and penalize
    def score(seq):
        pen = 0
        for k,v in cfix.items():
            pen += (c_k(seq,k)-v)**2
        return merit(seq) + 1000*pen

    cur = score(seq)
    improved = True
    while improved:
        improved = False
        order = free[:]
        random.shuffle(order)
        for i in order:
            seq[i] = -seq[i]
            ns = score(seq)
            if ns < cur:
                cur = ns
                improved = True
            else:
                seq[i] = -seq[i]
    if cons_ok(seq):
        m = merit(seq)
        if best_global is None or m < best_global[0]:
            best_global = (m, seq[:])
            print(restart, m)
            if m <= 62:
                break

print("best:", best_global)

